package atsscrape

import (
	"bytes"
	"context"
	"io"
	"net/http"
	"os"
	"strings"
	"testing"
)

func scriptClient(routes map[string]func(*http.Request) *http.Response) *http.Client {
	return &http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
		key := req.Method + " " + req.URL.String()
		if fn, ok := routes[key]; ok {
			return fn(req), nil
		}
		for pattern, fn := range routes {
			if strings.Contains(key, pattern) {
				return fn(req), nil
			}
		}
		return jsonBody(404, "missing "+key), nil
	})}
}

func TestEdgeGreenhouseRejectsHTTPError(t *testing.T) {
	client := scriptClient(map[string]func(*http.Request) *http.Response{
		"boards-api.greenhouse.io": func(req *http.Request) *http.Response {
			return jsonBody(404, `{"status":404}`)
		},
	})
	_, err := Scrape(context.Background(), client, Request{
		ATSType: "greenhouse",
		ATSURL:  "https://boards.greenhouse.io/acme",
	})
	if err == nil {
		t.Fatal("404 must be an error so auto mode can fall back to Python")
	}
}

