func TestEdgeSmartRecruitersPaginatesAndSkipsBlankID(t *testing.T) {
	var offsets []string
	client := scriptClient(map[string]func(*http.Request) *http.Response{
		"api.smartrecruiters.com": func(req *http.Request) *http.Response {
			offsets = append(offsets, req.URL.Query().Get("offset"))
			if req.URL.Query().Get("offset") == "0" {
				return jsonBody(200, `{"totalFound":2,"content":[
					{"name":"Backend","id":"1","location":{"city":"Berlin","country":"Germany"}},
					{"name":"No id"}
				]}`)
			}
			return jsonBody(200, `{"totalFound":2,"content":[
				{"name":"Platform","id":"2","location":{"fullLocation":"Amsterdam, Netherlands"}}
			]}`)
		},
	})
	jobs, err := Scrape(context.Background(), client, Request{
		ATSType: "smartrecruiters",
		ATSURL:  "https://jobs.smartrecruiters.com/Acme",
	})
	if err != nil {
		t.Fatal(err)
	}
	if strings.Join(offsets, ",") != "0,1" && strings.Join(offsets, ",") != "0,2" {
		t.Fatalf("offsets %v", offsets)
	}
	for _, job := range jobs {
		if strings.HasSuffix(job.URL, "/Acme/") || strings.HasSuffix(job.URL, "/Acme") {
			t.Fatalf("blank id kept: %#v", jobs)
		}
	}
	if len(jobs) != 2 {
		t.Fatalf("jobs %#v offsets %v", jobs, offsets)
	}
}

