func TestEdgeWorkdayPaginatesAndBuildsBase(t *testing.T) {
	api, base := workdayAPIAndBase("https://wd3.myworkdayjobs.com/wday/cxs/acme/External/jobs")
	if !strings.Contains(api, "/wday/cxs/acme/External/jobs") || base != "https://wd3.myworkdayjobs.com/en-US/External" {
		t.Fatalf("api=%s base=%s", api, base)
	}
	siteAPI, siteBase := workdayAPIAndBase("https://wd3.myworkdaysite.com/wday/cxs/tenant/site/jobs")
	if siteBase != "https://wd3.myworkdaysite.com/en-US/tenant/site" {
		t.Fatalf("site base %s api %s", siteBase, siteAPI)
	}
	pipedAPI, pipedBase := workdayAPIAndBase("https://x/wday/cxs/a/b/jobs|https://custom.example/jobs")
	if pipedBase != "https://custom.example/jobs" || strings.Contains(pipedAPI, "|") {
		t.Fatalf("piped api=%s base=%s", pipedAPI, pipedBase)
	}

	pages := 0
	client := scriptClient(map[string]func(*http.Request) *http.Response{
		"/wday/cxs/": func(req *http.Request) *http.Response {
			pages++
			body, _ := io.ReadAll(req.Body)
			if pages == 1 && !strings.Contains(string(body), `"offset":0`) {
				t.Fatalf("body %s", body)
			}
			if pages == 1 {
				return jsonBody(200, `{"total":2,"jobPostings":[{"title":"One","externalPath":"/job/one","locationsText":"Berlin"}]}`)
			}
			return jsonBody(200, `{"total":2,"jobPostings":[{"title":"Two","externalPath":"/job/two"}]}`)
		},
	})
	jobs, err := Scrape(context.Background(), client, Request{
		ATSType: "workday",
		ATSURL:  "https://wd3.myworkdayjobs.com/wday/cxs/acme/External/jobs",
	})
	if err != nil {
		t.Fatal(err)
	}
	if pages != 2 || len(jobs) != 2 || jobs[1].URL != "https://wd3.myworkdayjobs.com/en-US/External/job/two" {
		t.Fatalf("pages=%d jobs=%#v", pages, jobs)
	}
}

func TestEdgeWorkdayStopsAtCap(t *testing.T) {
