			pages++
			return jsonBody(200, `{"total":5000,"jobPostings":[{"title":"Role","externalPath":"/job/x"}]}`)
		},
	})
	jobs, err := Scrape(context.Background(), client, Request{
		ATSType: "workday",
		ATSURL:  "https://acme.myworkdayjobs.com/wday/cxs/acme/Careers/jobs",
	})
	if err != nil {
		t.Fatal(err)
	}
	if pages > 101 {
		t.Fatalf("pages %d exceeded cap", pages)
	}
	if len(jobs) == 0 {
		t.Fatal("expected jobs before cap")
	}
}

