func TestEdgeMainStdin(t *testing.T) {
	cases := []struct {
		name string
		in   string
		code int
	}{
		{"bad json", "{", 1},
		{"unsupported", `{"ats_type":"hibob","ats_url":"https://example.com"}`, 2},
		{"empty object", `{}`, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			oldIn, oldOut, oldErr := os.Stdin, os.Stdout, os.Stderr
			defer func() {
				os.Stdin, os.Stdout, os.Stderr = oldIn, oldOut, oldErr
			}()
			os.Stdin = io.NopCloser(strings.NewReader(tc.in))
			os.Stdout = &bytes.Buffer{}
			os.Stderr = &bytes.Buffer{}
			if got := Main(); got != tc.code {
				t.Fatalf("code %d want %d stderr %s", got, tc.code, os.Stderr.(*bytes.Buffer).String())
			}
		})
	}
}

